const CATEGORIES = ['billing', 'technical', 'shipping', 'account', 'general'];
const PRIORITIES = ['low', 'medium', 'high', 'urgent'];
const SENTIMENTS = ['negative', 'neutral', 'positive'];
/**
 * Pull a JSON object out of model text. Models often wrap JSON in markdown
 * fences or add a sentence before it, so try a few strategies in order.
 */
function extractJson(text) {
    if (typeof text !== 'string')
        return null;
    const trimmed = text.trim();
    const candidates = [trimmed];
    const fenced = trimmed.match(/```(?:json)?\s*([\s\S]*?)```/i);
    if (fenced)
        candidates.push(fenced[1].trim());
    const first = trimmed.indexOf('{');
    const last = trimmed.lastIndexOf('}');
    if (first !== -1 && last > first)
        candidates.push(trimmed.slice(first, last + 1));
    for (const candidate of candidates) {
        try {
            const parsed = JSON.parse(candidate);
            if (parsed !== null && typeof parsed === 'object' && !Array.isArray(parsed))
                return parsed;
        }
        catch {
            // try the next strategy
        }
    }
    return null;
}
function isOneOf(value, allowed) {
    return typeof value === 'string' && allowed.includes(value);
}
/** Check a parsed model answer against the triage contract and report every problem found. */
function validateTriage(raw, options = {}) {
    const minConfidence = options.minConfidence ?? 0.6;
    const maxSummaryChars = options.maxSummaryChars ?? 280;
    const maxReplyChars = options.maxReplyChars ?? 1200;
    const errors = [];
    if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) {
        return { valid: false, errors: ['The answer must be a single JSON object.'] };
    }
    const obj = raw;
    if (!isOneOf(obj.category, CATEGORIES))
        errors.push(`category must be one of: ${CATEGORIES.join(', ')}.`);
    if (!isOneOf(obj.priority, PRIORITIES))
        errors.push(`priority must be one of: ${PRIORITIES.join(', ')}.`);
    if (!isOneOf(obj.sentiment, SENTIMENTS))
        errors.push(`sentiment must be one of: ${SENTIMENTS.join(', ')}.`);
    if (typeof obj.summary !== 'string' || obj.summary.trim().length === 0) {
        errors.push('summary must be a non-empty string.');
    }
    else if (obj.summary.length > maxSummaryChars) {
        errors.push(`summary must be at most ${maxSummaryChars} characters.`);
    }
    if (typeof obj.suggested_reply !== 'string' || obj.suggested_reply.trim().length < 20) {
        errors.push('suggested_reply must be a string of at least 20 characters.');
    }
    else if (obj.suggested_reply.length > maxReplyChars) {
        errors.push(`suggested_reply must be at most ${maxReplyChars} characters.`);
    }
    if (typeof obj.needs_human !== 'boolean')
        errors.push('needs_human must be true or false.');
    if (typeof obj.confidence !== 'number' || Number.isNaN(obj.confidence) || obj.confidence < 0 || obj.confidence > 1) {
        errors.push('confidence must be a number between 0 and 1.');
    }
    else if (obj.confidence < minConfidence) {
        errors.push(`confidence ${obj.confidence} is below the minimum of ${minConfidence}; re-check the customer and knowledge base data.`);
    }
    if (errors.length > 0)
        return { valid: false, errors };
    return {
        valid: true,
        errors: [],
        result: {
            category: obj.category,
            priority: obj.priority,
            sentiment: obj.sentiment,
            summary: obj.summary.trim(),
            suggested_reply: obj.suggested_reply.trim(),
            needs_human: obj.needs_human,
            confidence: Math.round(obj.confidence * 100) / 100,
        },
    };
}
/** Turn validation errors into a feedback block that is appended to the retry prompt. */
function buildFeedback(errors) {
    const lines = errors.map((e, i) => `${i + 1}. ${e}`);
    return [
        'FEEDBACK: your previous answer was rejected by the validator.',
        ...lines,
        'Return only one corrected JSON object with exactly these keys: category, priority, sentiment, summary, suggested_reply, needs_human, confidence.',
    ].join('\n');
}
/** Rough token estimate (about 4 characters per token for English). Used only for monitoring. */
function estimateTokens(text) {
    return Math.ceil((text || '').length / 4);
}
function estimateCostUsd(promptTokens, outputTokens, rates) {
    const cost = (promptTokens * rates.inputPerMillion + outputTokens * rates.outputPerMillion) / 1000000;
    return Math.round(cost * 1000000) / 1000000;
}
/** Decide what happens after a validation pass. Pure function so the loop logic is testable. */
function nextStep(args) {
    if (!args.valid)
        return args.attempt < args.maxAttempts ? 'retry' : 'give_up';
    return args.needsHuman ? 'escalate' : 'finish';
}

const MAX_ATTEMPTS = 3;
const MIN_CONFIDENCE = 0.6;
const RATES = {"inputPerMillion":0.59,"outputPerMillion":0.79};
const MODEL = "openai/gpt-oss-120b";
const input = $('Build Prompt').item.json;
const raw = $json.output;
const parsed = extractJson(raw);
const check = validateTriage(parsed, { minConfidence: MIN_CONFIDENCE });
const errors = check.valid ? [] : (parsed === null
  ? ['The answer was not valid JSON. Return only a JSON object, with no prose and no code fences.']
  : check.errors);
const step = nextStep({ valid: check.valid, attempt: input.attempt, maxAttempts: MAX_ATTEMPTS, needsHuman: check.result ? check.result.needs_human : false });
const promptTokens = estimateTokens(input.prompt);
const outputTokens = estimateTokens(typeof raw === 'string' ? raw : JSON.stringify(raw));
return [{ json: {
  ticket: input.ticket,
  attempt: input.attempt,
  step,
  valid: check.valid,
  errors,
  result: check.result || null,
  run: {
    model: MODEL,
    latency_ms: Date.now() - input.startedAt,
    est_prompt_tokens: promptTokens,
    est_output_tokens: outputTokens,
    est_cost_usd: estimateCostUsd(promptTokens, outputTokens, RATES),
  },
} }];

